// Only previews generated by this crop session are written/removed. Never touch
// the selected original file or arbitrary paths supplied by an API response.
declare const wx: { env: { USER_DATA_PATH: string } }
export async function photoPreview(base64: string): Promise<{ url: string; dispose: () => void }> {
  // #ifdef MP-WEIXIN
  const fs = uni.getFileSystemManager()
  const filePath = `${wx.env.USER_DATA_PATH}/dazzy-crop-${Date.now()}-${Math.random().toString(36).slice(2)}.jpg`
  await new Promise<void>((resolve, reject) => fs.writeFile({ filePath, data: base64, encoding: 'base64', success: () => resolve(), fail: reject }))
  return { url: filePath, dispose: () => fs.unlink({ filePath, fail: () => {} }) }
  // #endif
  // #ifndef MP-WEIXIN
  return { url: `data:image/jpeg;base64,${base64}`, dispose: () => {} }
  // #endif
}
